import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec2, length, mix, smoothstep, sub } from 'three/tsl';
import { gsap } from 'gsap';
import { Group, Mesh, PlaneGeometry, CylinderGeometry, Color } from '@/primitives';

export default function createNode(config, ctx) {
  const root = new Group();
  const primitives = [];

  // ---------- Backdrop Gradient Plane ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const colorTop = new Color('#0b0b10');
  const colorMid = new Color('#101017');
  const colorBot = new Color('#16161d');

  const yCoord = uv().y;
  const gradMid = mix(colorTop, colorMid, smoothstep(0.0, 0.55, yCoord));
  const gradColor = mix(gradMid, colorBot, smoothstep(0.55, 1.0, yCoord));

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: gradColor,
    side: 2, // DoubleSide
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // ---------- Plinth ----------
  const plinthGeom = new CylinderGeometry(1.4, 1.4, 0.25, 32);
  const plinthMat = new MeshStandardNodeMaterial({
    color: new Color('#14141a'),
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new Mesh(plinthGeom, plinthMat);
  // top face at y = -1.1 => center y = -1.1 - height/2
  plinth.position.y = -1.1 - 0.125;
  root.add(plinth);

  // ---------- Contact Shadow ----------
  const shadowGeom = new PlaneGeometry(3.2, 3.2);
  const shadowColor = new Color('#000000');
  const uvCenter = sub(uv(), vec2(0.5));
  const dist = length(uvCenter);
  const opacityNode = smoothstep(0.0, 0.5, dist);
  const shadowMat = new MeshBasicNodeMaterial({
    colorNode: shadowColor,
    opacityNode,
    transparent: true,
    depthWrite: false,
  });
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.position.y = plinth.position.y - 0.125; // just below plinth base
  shadow.position.z = 0.01;
  root.add(shadow);

  // ---------- Load Watch Mesh ----------
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      root.add(gltf.scene);
    });
  }

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textColor = config.visualSpec?.colors?.paper ?? '#e8ecf2';
  let baseY = -1.5; // headline baseline
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 24,
      color: textColor,
      align: 'left',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    txt.position.set(-3, baseY, 0);
    root.add(txt);
    // advance Y based on role
    if (item.role === 'headline') baseY -= 0.34;
    else if (item.role === 'body') baseY -= 0.2;
    else if (item.role === 'caption') baseY -= 0.09;
    else baseY -= 0.15;
  }

  // ---------- Cinematic Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        primitives.push(instance);
      }
    }
  }

  // ---------- Entrance Animation ----------
  const entrance = gsap.timeline();
  entrance.from(root.position, { y: 0.4, duration: 0.7, ease: 'power3.out' });
  entrance.from(root.scale, { x: 0.9, y: 0.9, z: 0.9, duration: 0.5, ease: 'power2.out' }, '<');
  entrance.play();

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    entrance.kill();
    for (const p of primitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    // dispose materials & geometries
    backdrop.geometry.dispose();
    backdropMat.dispose();
    plinth.geometry.dispose();
    plinthMat.dispose();
    shadow.geometry.dispose();
    shadowMat.dispose();
  };

  // ---------- Event Handlers Placeholder ----------
  root.userData.handlers = {};

  return root;
}
